export const MAX_THEME_BYTES = 512 * 1024;
const validId = (id: string) => /^[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}$/.test(id);

interface ThemeRow {
  document: string;
  etag: string;
  updated_at: string;
}

/** Public GET: the body is the complete host-owned JSON, without an API envelope. */
export async function handleGetAppTheme(request: Request, id: string, env: Env): Promise<Response> {
  if (!validId(id)) return errorResponse(400, 'Invalid theme ID');
  const row = await env.DB.prepare('SELECT document, etag, updated_at FROM app_themes WHERE id = ?')
    .bind(id).first<ThemeRow>();
  if (!row) return errorResponse(404, 'Theme not published');

  const headers = {
    'Content-Type': 'application/json; charset=utf-8',
    // Revalidate with D1 on every request so publishing takes effect immediately.
    'Cache-Control': 'public, no-cache',
    'ETag': row.etag,
    'Last-Modified': new Date(row.updated_at).toUTCString(),
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Expose-Headers': 'ETag, Last-Modified',
  };
  const matches = request.headers.get('If-None-Match')?.split(',')
    .some(value => value.trim() === '*' || value.trim().replace(/^W\//, '') === row.etag);
  return new Response(matches ? null : row.document, { status: matches ? 304 : 200, headers });
}

