/// The theme baked into the app at build time — `WAC/Helper Class/Theme/Theme.json`.
static var bundled: Theme {
    guard let url = Bundle.main.url(forResource: "Theme", withExtension: "json"),
          let data = try? Data(contentsOf: url),
          let theme = try? JSONDecoder().decode(Theme.self, from: data) else {
        assertionFailure("Theme.json missing or malformed in bundle — using compiled fallback")
