RipulThemeEngine.exportThemeDocument = { draft in
    let source = draft ?? RipulThemeEngine.remoteTheme?.authoritativeDocument
        ?? Data(exportJSON(bundled).utf8)
    var json = try JSONSerialization.jsonObject(with: source) as! [String: Any]
    let live = try JSONSerialization.jsonObject(with: Data(exportJSON().utf8)) as! [String: Any]
    for (key, value) in live {
        // A supplied publication draft owns its behavioural envelope. An unrelated
        // colour edit must not replace it with this binary's active fallback.
        if key == "jobKindCatalogue", json[key] != nil {
            if let authored = jobKindPublicationOverride {
                json[key] = try JSONSerialization.jsonObject(with: authored.encoded())
            }
            continue
        }
        if json[key] == nil, let map = value as? [String: Any], map.isEmpty { continue }
        json[key] = value
    }
    return try JSONSerialization.data(withJSONObject: json, options: [.sortedKeys, .prettyPrinted])
}
// WAC's extras for the SDK's get_app_diagnostics tool.

