    static let bundledTips: [String: [String: RipulKnob]] = bundled.tips

    /// Apply a new live theme: update `current`, persist the whole blob (engine slice +
    /// extras), then have the engine adopt the slice — it posts `.ripulThemeDidChange`
    /// (WAC's `.themeDidChange` alias) and repaints token-tagged UIKit views. Also posts
    /// `accentDidChange` — accent lives in the theme now, so long-lived accent-tinted UI
    /// (tab bar, etc.) that observes it re-applies whenever the theme changes.
    static func apply(_ theme: Theme) {
        jobKinds.receive(theme.jobKindCatalogue)
        current = theme
        if let json = encode(theme) { UserDefaults.standard.set(json, forKey: overrideKey) }
        RipulThemeEngine.adopt(theme.engineDocument)
        NotificationCenter.default.post(name: ThemeManager.accentDidChange, object: nil)

