// For CMS query/mutation runs, derive the site key from the cmsDefinitionId in the URL
// and retry with its portalAuth.jwksUrl if Ripul's JWKS failed (BYOA portals).
if (!user && token && request.method === 'POST') {
  const cmsRunMatch = path.match(/^\/v1\/cms-definitions\/([^/]+)\/(queries|mutations)\/[^/]+\/(run|lookup)$/);
  if (cmsRunMatch) {
    const cmsId = cmsRunMatch[1];
    const sk = await getSiteKeyByCmsDefinitionId(cmsId, env);
    const customJwksUrl = sk?.portalAuth?.provider === 'clerk' ? sk.portalAuth.jwksUrl : undefined;
    if (customJwksUrl) {
      console.log('[Auth] Trying portal custom JWKS for cmsId:', cmsId);
      user = await verifyClerkJwt(token, env, customJwksUrl);
      console.log('[Auth] Portal CMS JWKS result:', user ? `success - user ${user.sub}` : 'FAILED');
      if (user) portalAuthSource = 'byoa';
    }
  }
}

// Delegated design save from a BYOA portal: the designer is authed by the
// customer's IdP, so their token won't verify against Ripul's JWKS. Derive
// the site key from the cmsId and retry against the portal's custom JWKS,
// exactly like query/mutation runs. Once verified, the /design handler
// authorizes them by their verified email → site-key design role.
if (!user && token) {
