async function cacheKey(scope: string, credentialValues: string[]): Promise<string> {
  const data = new TextEncoder().encode([scope, ...credentialValues].join(':'));
  const digest = await crypto.subtle.digest('SHA-256', data);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

/** Walk a dotted path (e.g. "user.id") into a JSON value; coerce to string. */
function readPath(obj: unknown, path: string): string | null {
  let cur: unknown = obj;
  for (const seg of path.split('.')) {
    if (cur && typeof cur === 'object' && seg in (cur as Record<string, unknown>)) {
      cur = (cur as Record<string, unknown>)[seg];
    } else {
      return null;
    }
  }
  if (typeof cur === 'string') return cur;
  if (typeof cur === 'number') return String(cur);
  return null;
}

/**
 * Validate the request's credential headers against the configured origin
 * endpoint and extract the principal. Returns null when credentials are
 * absent/invalid or the config is broken (caller falls through to 401 —
 * never 500).
 */
export async function resolveOpaquePrincipal(
  request: Request,
  config: PortalAuthConfigOpaque,
  siteKey: SiteKey,
  env: Env,
): Promise<OpaquePrincipal | null> {
  if (!config.credentialHeaders?.length) return null;
  if (!config.credentialHeaders.every((h) => request.headers.get(h) !== null)) return null;
  const credentialValues = config.credentialHeaders.map((h) => request.headers.get(h) as string);

  const key = await cacheKey(`portal:${siteKey.id}`, credentialValues);
  const now = Date.now();
  const hit = cache.get(key);
  if (hit && hit.expiresAt > now) return hit.principal;
  if (hit) cache.delete(key);

  // The origin lives on the linked CMS definition (honouring delegation).
  let cmsDefinitionId = siteKey.cmsDefinitionId;
  if (siteKey.delegateCmsDefinitionTo) {
    const delegateKey = await getSiteKeyById(siteKey.delegateCmsDefinitionTo, env);
    if (delegateKey?.cmsDefinitionId) cmsDefinitionId = delegateKey.cmsDefinitionId;
  }
  const cms = cmsDefinitionId
    ? await getCmsDefinitionById(cmsDefinitionId, siteKey.organizationId, env)
    : null;
  const origin = (cms?.origins ?? []).find((o) => o.id === config.originId);
  if (!origin) {
    console.error(`[opaquePortalAuth] siteKey ${siteKey.id} references unknown origin "${config.originId}"`);
    return null;
  }

  const base = origin.baseUrl.replace(/\/+$/, '');
  const url = `${base}${config.path}`;
  // Forward the caller's OWN headers so the validation call is
  // indistinguishable from the app's real request — bare requests (creds only)
  // are rejected by upstreams that gate on a WAF or version headers (e.g. WAC).
  const headers = new Headers(request.headers);
  for (const h of ['host', 'content-length', 'connection', 'keep-alive', 'transfer-encoding', 'upgrade', 'x-site-key', 'authorization']) {
    headers.delete(h);
  }
  for (const h of config.credentialHeaders) headers.set(h, request.headers.get(h) as string);
  headers.set('accept', 'application/json');

  let res: Response;
  try {
    res = await fetch(url, { method: config.method ?? 'GET', headers });
  } catch (e) {
    console.error(`[opaquePortalAuth] validation request failed for siteKey ${siteKey.id}:`, e);
    return null;
  }
  if (!res.ok) {
    console.warn(`[opaquePortalAuth] siteKey ${siteKey.id} validation -> ${res.status} at ${config.path}`);
    return null;
  }

  let body: unknown;
  try {
    body = await res.json();
  } catch {
    console.warn(`[opaquePortalAuth] siteKey ${siteKey.id} validation returned non-JSON at ${config.path}`);
    return null;
  }
  const id = readPath(body, config.principalIdPath);
  if (!id) {
    console.warn(`[opaquePortalAuth] siteKey ${siteKey.id} no principal at "${config.principalIdPath}"`);
    return null;
  }
  const principal: OpaquePrincipal = {
    id,
    email: (config.principalEmailPath && readPath(body, config.principalEmailPath)) || undefined,
    display: (config.principalDisplayPath && readPath(body, config.principalDisplayPath)) || undefined,
  };

  const ttlSeconds = config.cacheTtlSeconds ?? DEFAULT_TTL_SECONDS;
  cache.set(key, { principal, expiresAt: now + ttlSeconds * 1000 });
  return principal;
}

/**
 * Full opaque portal authentication for a resolved site key: validate the
 * credential, then apply the membership gate (blocked always refused;
 * invite-only requires an owner row). Returns the synthetic user or null.
 */
export async function verifyOpaquePortalUser(
  request: Request,
  siteKey: SiteKey | null,
  env: Env,
): Promise<OpaquePortalUser | null> {
  // Two-slot resolution: the dedicated opaque slot coexists with a Clerk/JWKS
  // `portalAuth` (browser IdP) on the same key; opaque-only portals may store
  // the config in `portalAuth` itself instead.
  const config = siteKey?.portalAuthOpaque
    ?? (siteKey?.portalAuth?.provider === 'opaque' ? siteKey.portalAuth : null);
  if (!siteKey || !config) return null;

  const principal = await resolveOpaquePrincipal(request, config, siteKey, env);
  if (!principal) return null;

  const sub = `${config.subPrefix ?? 'opaque'}:${principal.id}`;
  const owner = await getSiteKeyOwner(siteKey.id, sub, env);
  if (owner?.status === 'blocked') {
    console.warn(`[opaquePortalAuth] refused blocked member ${sub} on siteKey ${siteKey.id}`);
    return null;
  }
  if (!owner && (siteKey.membershipPolicy ?? 'open') === 'invite-only') {
    console.warn(`[opaquePortalAuth] refused non-member ${sub} on invite-only siteKey ${siteKey.id}`);
    return null;
  }

  // NO email claim: the upstream email is unverified and must never join
  // against owner rows the way a JWKS-verified claim does.
  const nowSec = Math.floor(Date.now() / 1000);
  const user: ClerkJwtPayload = {
    sub,
    iat: nowSec,
    exp: nowSec + (config.cacheTtlSeconds ?? DEFAULT_TTL_SECONDS),
    iss: `portal-opaque:${siteKey.id}`,
  };
  console.log(`[opaquePortalAuth] authenticated ${sub} on siteKey ${siteKey.id} (member: ${!!owner})`);
  return { user, principalId: principal.id, owner };
}

