  new Request(`https://example.com/admin/app-themes/${id}`, { method: 'PUT', body }), id, ctx, env,
);
const get = (id: string, etag?: string) => handleGetAppTheme(
  new Request(`https://example.com/v1/app-themes/${id}`, { headers: etag ? { 'If-None-Match': etag } : {} }), id, env,
);

beforeAll(async () => {
  mf = new Miniflare({ modules: true, script: 'export default { fetch() { return new Response("ok") } }', d1Databases: ['DB'] });
  const db = await mf.getD1Database('DB');
  const migration = readFileSync(new URL('../../migrations/0044_create_app_themes.sql', import.meta.url), 'utf8');
  await db.prepare(migration).run();
  env = { DB: db } as unknown as Env;
});
afterAll(async () => { await mf?.dispose(); });

