/** Admin PUT: publish the entire manifest atomically. Omitted keys are removed. */
export async function handlePublishAppTheme(
  request: Request, id: string, ctx: AuthContext, env: Env,
): Promise<Response> {
  if (!PermissionResolver.hasPermission(ctx, 'admin:manage_site_keys')) {
    return errorResponse(403, 'Permission denied: admin:manage_site_keys required');
  }
  if (!validId(id)) return errorResponse(400, 'Invalid theme ID');
  if (Number(request.headers.get('Content-Length')) > MAX_THEME_BYTES) {
    return errorResponse(413, 'Theme exceeds 512 KiB');
  }
  // Bound chunked uploads too, before parsing or writing anything.
  const reader = request.body?.getReader();
  if (!reader) return errorResponse(400, 'Expected a JSON object');
  const chunks: Uint8Array[] = [];
  let length = 0;
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      length += value.byteLength;
      if (length > MAX_THEME_BYTES) {
        await reader.cancel();
        return errorResponse(413, 'Theme exceeds 512 KiB');
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }

