# 2. admin handler -> shared writer
old="""/** Admin PUT: publish the entire manifest atomically. Omitted keys are removed. */
export async function handlePublishAppTheme(
  request: Request, id: string, ctx: AuthContext, env: Env,
): Promise<Response> {
  if (!PermissionResolver.hasPermission(ctx, 'admin:manage_site_keys')) {
    return errorResponse(403, 'Permission denied: admin:manage_site_keys required');
  }
  if (!validId(id)) return errorResponse(400, 'Invalid theme ID');
"""
new="""const isAdmin = (ctx: AuthContext) => PermissionResolver.hasPermission(ctx, 'admin:manage_site_keys');
/** History kept per theme. Older versions are pruned on publish. */
export const MAX_THEME_VERSIONS = 100;

/** The site key a theme belongs to, or null when it has none (admin-only) or does not exist. */
export async function getAppThemeSiteKeyId(id: string, env: Env): Promise<string | null> {
  if (!validId(id)) return null;
  const row = await env.DB.prepare('SELECT site_key_id FROM app_themes WHERE id = ?')
    .bind(id).first<{ site_key_id: string | null }>();
  return row?.site_key_id ?? null;
}

/**
 * Why `ctx` may NOT publish (or read the history of) theme `id`, or null when it
 * may, with the label recorded against its publications. Global admins always
 * may. Otherwise the theme must belong to a site key, and the caller must be an
 * active member of that site key whose role is in the linked CMS definition's
 * `designRoles` — the same people who may design that site's portal. Members
 * are matched on user id, then on a VERIFIED email claim (opaque app logins
 * such as WAC carry none, so they match on `wac:<id>` only). Creating a theme
 * stays admin-only, so nobody can claim an id.
 */
export async function appThemePublishDenial(
  id: string, ctx: AuthContext, env: Env,
): Promise<{ denied: Response } | { label: string }> {
  if (isAdmin(ctx)) return { label: ctx.email ?? ctx.userId ?? 'admin' };
  const denied = (message: string) => ({ denied: errorResponse(403, message) });
  if (!validId(id)) return { denied: errorResponse(400, 'Invalid theme ID') };
  const row = await env.DB.prepare('SELECT site_key_id FROM app_themes WHERE id = ?')
    .bind(id).first<{ site_key_id: string | null }>();
  if (!row) return denied('Only a Ripul admin can create a new app theme');
  if (!row.site_key_id) return denied('This theme is not linked to a site, so only a Ripul admin can publish it');
  const sk = await getSiteKeyById(row.site_key_id, env);
  if (!sk) return denied('This theme is not linked to a site, so only a Ripul admin can publish it');
  let cmsId = sk.cmsDefinitionId;
  if (sk.delegateCmsDefinitionTo) {
    const delegate = await getSiteKeyById(sk.delegateCmsDefinitionTo, env);
    if (delegate?.cmsDefinitionId) cmsId = delegate.cmsDefinitionId;
  }
  const cms = cmsId ? await getCmsDefinitionById(cmsId, sk.organizationId, env) : null;
  let owner = ctx.userId ? await getSiteKeyOwner(sk.id, ctx.userId, env) : null;
  if (!owner && ctx.email) owner = await getSiteKeyOwnerByEmail(sk.id, ctx.email, env);
  const designRoles = cms?.designRoles ?? [];
  if (!owner || owner.status === 'blocked' || !designRoles.includes(owner.role)) {
    const roles = designRoles.length ? designRoles.join(' or ') : 'a design role';
    return denied(`Publishing this theme needs the ${roles} role on ${sk.name ?? 'its site'}`);
  }
  return { label: owner.email ?? ctx.email ?? owner.userId };
}

/**
 * Admin PUT: publish the entire manifest atomically. Omitted keys are removed.
 * `?siteKeyId=` links the theme to a site so its designers can publish too
 * (`?siteKeyId=` with no value unlinks it).
 */
export async function handlePublishAppTheme(
  request: Request, id: string, ctx: AuthContext, env: Env,
): Promise<Response> {
  if (!isAdmin(ctx)) {
    return errorResponse(403, 'Permission denied: admin:manage_site_keys required');
  }
  if (!validId(id)) return errorResponse(400, 'Invalid theme ID');
  const siteKeyId = new URL(request.url).searchParams.get('siteKeyId');
  if (siteKeyId && !(await getSiteKeyById(siteKeyId, env))) return errorResponse(400, 'Unknown site key');
  const response = await writeTheme(request, id, ctx.userId ?? 'admin', ctx.email ?? ctx.userId ?? 'admin', env);
  if (response.ok && siteKeyId !== null) {
    await env.DB.prepare('UPDATE app_themes SET site_key_id = ? WHERE id = ?').bind(siteKeyId || null, id).run();
  }
  return response;
}

/** Site PUT `/v1/app-themes/:id`: the same publication, for the theme's site designers. */
export async function handleMemberPublishAppTheme(
  request: Request, id: string, ctx: AuthContext, env: Env,
): Promise<Response> {
  const access = await appThemePublishDenial(id, ctx, env);
  if ('denied' in access) return access.denied;
  return writeTheme(request, id, ctx.userId ?? 'unknown', access.label, env);
}

/** GET `/v1/app-themes/:id/versions`: the publication history, newest first, without documents. */
export async function handleListAppThemeVersions(id: string, ctx: AuthContext, env: Env): Promise<Response> {
  const access = await appThemePublishDenial(id, ctx, env);
  if ('denied' in access) return access.denied;
  const { results } = await env.DB.prepare(`SELECT id, etag, published_at, published_by, published_by_label,
      length(document) AS bytes FROM app_theme_versions WHERE theme_id = ? ORDER BY id DESC`)
    .bind(id).all<VersionRow>();
  return jsonResponse({ versions: results.map(versionSummary) });
}

/** GET `/v1/app-themes/:id/versions/:versionId`: one earlier publication's complete document. */
export async function handleGetAppThemeVersion(
  id: string, versionId: string, ctx: AuthContext, env: Env,
): Promise<Response> {
  const access = await appThemePublishDenial(id, ctx, env);
  if ('denied' in access) return access.denied;
  const row = await env.DB.prepare(`SELECT id, etag, document, published_at, published_by, published_by_label,
      length(document) AS bytes FROM app_theme_versions WHERE theme_id = ? AND id = ?`)
    .bind(id, Number(versionId)).first<VersionRow & { document: string }>();
  if (!row) return errorResponse(404, 'Version not found');
  return jsonResponse({ ...versionSummary(row), document: JSON.parse(row.document) });
}

interface VersionRow {
  id: number; etag: string; published_at: string; published_by: string;
  published_by_label: string | null; bytes: number;
}
const versionSummary = (row: VersionRow) => ({
  id: row.id, etag: row.etag, publishedAt: row.published_at,
  publishedBy: row.published_by_label ?? row.published_by, bytes: row.bytes,
});

async function writeTheme(
  request: Request, id: string, userId: string, label: string, env: Env,
): Promise<Response> {
"""
