  if (!row) return errorResponse(404, 'Version not found');
  return jsonResponse({ ...versionSummary(row), document: JSON.parse(row.document) });
}

interface VersionRow {
  id: number; etag: string; published_at: string; published_by: string;
  published_by_label: string | null; bytes: number;
}
const versionSummary = (row: VersionRow) => ({
  id: row.id, etag: row.etag, publishedAt: row.published_at,
  publishedBy: row.published_by_label ?? row.published_by, bytes: row.bytes,
});

async function writeTheme(
  request: Request, id: string, userId: string, label: string, env: Env,
): Promise<Response> {
"""
