s=s.replace(".bind(id, document, etag, updatedAt, ctx.userId).run();",".bind(id, document, etag, updatedAt, userId).run();")
old="""  return jsonResponse({ id, etag, updatedAt, url: `/v1/app-themes/${id}` });
}"""
new="""  // Record it in the history; keep the newest MAX_THEME_VERSIONS.
  await env.DB.batch([
    env.DB.prepare(`INSERT INTO app_theme_versions (theme_id, etag, document, published_at, published_by,
      published_by_label) VALUES (?, ?, ?, ?, ?, ?)`).bind(id, etag, document, updatedAt, userId, label),
    env.DB.prepare(`DELETE FROM app_theme_versions WHERE theme_id = ? AND id NOT IN
      (SELECT id FROM app_theme_versions WHERE theme_id = ? ORDER BY id DESC LIMIT ?)`)
      .bind(id, id, MAX_THEME_VERSIONS),
  ]);
  return jsonResponse({ id, etag, updatedAt, url: `/v1/app-themes/${id}` });
}"""
