  it('uses existing admin permissions for publication', async () => {
    const reader = { userId: 'reader', permissions: new Set() } as AuthContext;
    expect((await publish('unauthorized', '{}', reader)).status).toBe(403);
    expect((await get('unauthorized')).status).toBe(404);
  });

  it('isolates theme IDs and rejects invalid identifiers', async () => {
    await publish('release', '{"channel":"production"}');
    await publish('release.beta', '{"channel":"beta"}');
    expect(await (await get('release')).json()).toEqual({ channel: 'production' });
    expect(await (await get('release.beta')).json()).toEqual({ channel: 'beta' });
    expect((await get('missing')).status).toBe(404);
    expect((await publish('../escape', '{}')).status).toBe(400);
  });

  it('rejects stale phone drafts atomically and preserves the newer publication', async () => {
    await publish('phone', '{"copy":"original","extras":[1,2]}');
    const etag = (await get('phone')).headers.get('ETag')!;
    const save = (copy: string, headers: Record<string, string>) => handlePublishAppTheme(
      new Request('https://example.com/admin/app-themes/phone', {
        method: 'PUT', headers, body: JSON.stringify({ copy, extras: [1, 2] }),
      }), 'phone', admin, env,
    );
    const results = await Promise.all([
      save('first', { 'If-Match': etag }), save('second', { 'If-Match': etag }),
    ]);
    expect(results.map(r => r.status).sort()).toEqual([200, 412]);
    const winning = await (await get('phone')).json();
    expect((await save('stale', { 'If-Match': etag })).status).toBe(412);
    expect((await save('create', { 'If-None-Match': '*' })).status).toBe(412);
    expect(await (await get('phone')).json()).toEqual(winning);
  });

  it('allows conditional first publication only once', async () => {
    const save = () => handlePublishAppTheme(new Request('https://example.com', {
      method: 'PUT', headers: { 'If-None-Match': '*' }, body: '{}',
    }), 'new-phone', admin, env);
    expect((await save()).status).toBe(200);
    expect((await save()).status).toBe(412);
  });
});

