s += """
describe('site designers', () => {
  const member = (userId: string, email?: string) =>
    ({ userId, email, authSource: 'clerk_jwt', permissions: new Set() }) as unknown as AuthContext;
  const memberPublish = (id: string, body: string, ctx: AuthContext) => handleMemberPublishAppTheme(
    new Request(`https://example.com/v1/app-themes/${id}`, { method: 'PUT', body }), id, ctx, env,
  );
  const link = (id: string, siteKeyId: string, body = '{"v":0}') => handlePublishAppTheme(
    new Request(`https://example.com/admin/app-themes/${id}?siteKeyId=${siteKeyId}`, { method: 'PUT', body }),
    id, admin, env,
  );

  it('lets a site designer publish the site theme, and nobody else', async () => {
    expect((await link('site-theme', 'sk_app')).status).toBe(200);
    expect((await memberPublish('site-theme', '{"v":1}', member('wac:1'))).status).toBe(200);
    expect(await (await get('site-theme')).json()).toEqual({ v: 1 });
    const manager = await memberPublish('site-theme', '{"v":2}', member('wac:2'));
    expect(manager.status).toBe(403);
    expect(((await manager.json()) as { error: { message: string } }).error.message ?? '').toContain('admin');
    expect((await memberPublish('site-theme', '{"v":2}', member('wac:3'))).status).toBe(403);
    expect((await memberPublish('site-theme', '{"v":2}', member('wac:999'))).status).toBe(403);
    expect(await (await get('site-theme')).json()).toEqual({ v: 1 });
  });

  it('matches a Ripul or SSO designer by verified email', async () => {
    await link('email-theme', 'sk_app');
    expect((await memberPublish('email-theme', '{"v":"eden"}', member('user_other', 'eden@example.com'))).status).toBe(200);
  });

  it('keeps unlinked and new themes admin-only', async () => {
    await publish('admin-only', '{"v":0}');
    expect((await memberPublish('admin-only', '{"v":1}', member('wac:1'))).status).toBe(403);
    expect((await memberPublish('brand-new', '{"v":1}', member('wac:1'))).status).toBe(403);
    expect((await get('brand-new')).status).toBe(404);
    expect((await link('unlinked-later', 'sk_app')).status).toBe(200);
    await handlePublishAppTheme(new Request('https://example.com/admin/app-themes/unlinked-later?siteKeyId=',
      { method: 'PUT', body: '{"v":0}' }), 'unlinked-later', admin, env);
    expect((await memberPublish('unlinked-later', '{"v":1}', member('wac:1'))).status).toBe(403);
    expect((await link('bad-site', 'sk_missing')).status).toBe(400);
  });

  it('records every publication and serves earlier documents to designers', async () => {
    await link('history', 'sk_app', '{"v":"first"}');
    await memberPublish('history', '{"v":"second"}', member('wac:1'));
    await memberPublish('history', '{"v":"third"}', member('user_designer', 'eden@example.com'));
    const list = await handleListAppThemeVersions('history', member('wac:1'), env);
    expect(list.status).toBe(200);
    const { versions } = await list.json() as { versions: { id: number; publishedBy: string; etag: string }[] };
    expect(versions.map(v => v.publishedBy)).toEqual(['eden@example.com', 'wac:1', 'theme-author']);
    expect(versions[0].etag).toBe((await get('history')).headers.get('ETag'));
    const first = await handleGetAppThemeVersion('history', String(versions[2].id), member('wac:1'), env);
    expect(((await first.json()) as { document: unknown }).document).toEqual({ v: 'first' });
