/// Opaque portal credentials for CMS member mode: the SAME
/// `secret`/`secret-id` headers every WAC API call carries. Ripul
/// forwards them to WAC's `GET /api/v1/user`, so being logged into WAC
/// IS being signed into the portal (member id `wac:<user.id>` — no
/// second login). Returns nil when logged out; the renderer then shows
/// its no-access state on invite-only portals.
static func portalCredentials() -> [String: String]? {
    let secret = preference.secret
    let secretId = preference.secret_id
    guard !secret.isEmpty, !secretId.isEmpty else { return nil }
    // Mirror NetworkHelper.getHeader(): Ripul forwards the caller's
    // headers to WAC's validation endpoint, and that request must look
    // like a genuine app call — WAC's edge rejects bare credential-only
    // requests.
    var headers: [String: String] = [
        Key.secret: secret,
        Key.secret_id: secretId,
        Key.HTTP_LOCALE: "en",
