  return 'cms_' + generateRandomString(12);
}

export async function getCmsDefinitionById(
  id: string,
  organizationId: string,
  env: Env
): Promise<CmsDefinition | null> {
  return store.getById(env.DB, organizationId, id);
}

/**
 * Look up a CMS definition by its globally-unique portal slug. Cross-org
 * (the slug carries no org disambiguator — that's the point of having
 * `?portalSlug=X` route directly to a single CMS).
 */
export async function getCmsDefinitionBySlug(
  slug: string,
  env: Env
): Promise<CmsDefinition | null> {
  const row = await env.DB
    .prepare('SELECT * FROM cms_definitions WHERE slug = ?')
    .bind(slug)
    .first<CmsDefinitionRow>();
  if (!row) return null;
  try {
    return JSON.parse(row.data) as CmsDefinition;
  } catch (e) {
    console.error(`[cms_definitions] corrupt JSON for id=${row.id}:`, e);
    return null;
  }
}

